import hashlib
import hmac
import itertools
import re
import secrets
import threading

try:
    from gateway import GatewayTimeout
except ImportError:  # pragma: no cover
    class GatewayTimeout(Exception):
        pass

_USERNAME_RE = re.compile(r"[a-z0-9_]{3,32}")


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


class Service:
    def __init__(self, clock, gateway, token_ttl=3600):
        self._clock = clock
        self._gateway = gateway
        self._ttl = token_ttl
        self._lock = threading.RLock()
        self._users = {}      # username -> (salt, hash)
        self._tokens = {}     # token -> (username, created)
        self._docs = {}       # id -> dict (internal, includes _seq)
        self._doc_counter = itertools.count(1)
        self._cursors = {}    # cursor -> (username, last_seq)
        self._payments = {}   # username -> list of payments
        self._pay_keys = {}   # (username, key) -> {"amount": int, "payment": dict|None}
        self._pay_counter = itertools.count(1)

    # ---- helpers ----
    @staticmethod
    def _hash(password, salt):
        return hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, 1000)

    def _auth(self, token):
        if not isinstance(token, str):
            return None
        entry = self._tokens.get(token)
        if entry is None:
            return None
        user, created = entry
        if self._clock.now() < created + self._ttl:
            return user
        return None

    @staticmethod
    def _public(doc):
        return {k: doc[k] for k in ("id", "owner", "title", "content", "created_at")}

    @staticmethod
    def _valid_doc(title, content):
        if not isinstance(title, str) or not (1 <= len(title) <= 200):
            return False
        if not isinstance(content, str) or len(content) > 100000:
            return False
        return True

    def _user_docs(self, user):
        docs = [d for d in self._docs.values() if d["owner"] == user]
        docs.sort(key=lambda d: d["_seq"])
        return docs

    def _own(self, user, doc_id):
        if not isinstance(doc_id, str):
            return None
        d = self._docs.get(doc_id)
        if d is None or d["owner"] != user:
            return None
        return d

    # ---- auth ----
    def register(self, username, password):
        with self._lock:
            if not isinstance(username, str) or not _USERNAME_RE.fullmatch(username):
                return 400, None
            if not isinstance(password, str) or len(password) < 8:
                return 400, None
            if username in self._users:
                return 409, None
            salt = secrets.token_bytes(16)
            self._users[username] = (salt, self._hash(password, salt))
            return 201, None

    def login(self, username, password):
        with self._lock:
            if not isinstance(username, str) or not isinstance(password, str):
                return 401, None
            rec = self._users.get(username)
            if rec is None:
                return 401, None
            salt, h = rec
            if not hmac.compare_digest(h, self._hash(password, salt)):
                return 401, None
            token = secrets.token_hex(16)
            while token in self._tokens:
                token = secrets.token_hex(16)
            self._tokens[token] = (username, self._clock.now())
            return 200, {"token": token}

    def logout(self, token):
        with self._lock:
            if self._auth(token) is None:
                return 401, None
            del self._tokens[token]
            return 204, None

    # ---- documents ----
    def create_document(self, token, title, content):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not self._valid_doc(title, content):
                return 400, None
            n = next(self._doc_counter)
            doc_id = "doc-%d" % n
            self._docs[doc_id] = {
                "id": doc_id, "owner": user, "title": title, "content": content,
                "created_at": self._clock.now(), "_seq": n,
            }
            return 201, {"id": doc_id}

    def get_document(self, token, doc_id):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            d = self._own(user, doc_id)
            if d is None:
                return 404, None
            return 200, self._public(d)

    def update_document(self, token, doc_id, title, content):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            d = self._own(user, doc_id)
            if d is None:
                return 404, None
            if not self._valid_doc(title, content):
                return 400, None
            d["title"] = title
            d["content"] = content
            return 200, self._public(d)

    def delete_document(self, token, doc_id):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            d = self._own(user, doc_id)
            if d is None:
                return 404, None
            del self._docs[doc_id]
            return 204, None

    def list_documents(self, token, page_size=20, cursor=None):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not _is_int(page_size) or not (1 <= page_size <= 100):
                return 400, None
            last_seq = 0
            if cursor is not None:
                if not isinstance(cursor, str):
                    return 400, None
                entry = self._cursors.get(cursor)
                if entry is None or entry[0] != user:
                    return 400, None
                last_seq = entry[1]
            remaining = [d for d in self._user_docs(user) if d["_seq"] > last_seq]
            page = remaining[:page_size]
            next_cursor = None
            if len(remaining) > page_size:
                next_cursor = secrets.token_hex(16)
                while next_cursor in self._cursors:
                    next_cursor = secrets.token_hex(16)
                self._cursors[next_cursor] = (user, page[-1]["_seq"])
            return 200, {"items": [self._public(d) for d in page],
                         "next_cursor": next_cursor}

    def search_documents(self, token, query):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not isinstance(query, str) or query == "":
                return 400, None
            q = query.lower()
            res = [self._public(d) for d in self._user_docs(user)
                   if q in d["title"].lower() or q in d["content"].lower()]
            return 200, res

    def export_documents(self, token):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            return 200, [self._public(d) for d in self._user_docs(user)]

    # ---- payments ----
    def pay(self, token, amount_cents, idempotency_key):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not _is_int(amount_cents) or not (1 <= amount_cents <= 1000000):
                return 400, None
            if not isinstance(idempotency_key, str) or idempotency_key == "":
                return 400, None
            k = (user, idempotency_key)
            rec = self._pay_keys.get(k)
            if rec is not None:
                if rec["amount"] != amount_cents:
                    return 409, None
                if rec["payment"] is not None:
                    return 200, dict(rec["payment"])
            try:
                self._gateway.charge("%s:%s" % (user, idempotency_key), amount_cents)
            except GatewayTimeout:
                if rec is None:
                    self._pay_keys[k] = {"amount": amount_cents, "payment": None}
                return 504, None
            payment = {
                "id": "pay-%d" % next(self._pay_counter),
                "amount_cents": amount_cents,
                "idempotency_key": idempotency_key,
                "created_at": self._clock.now(),
            }
            self._pay_keys[k] = {"amount": amount_cents, "payment": payment}
            self._payments.setdefault(user, []).append(payment)
            return 201, dict(payment)

    def list_payments(self, token):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            return 200, [dict(p) for p in self._payments.get(user, [])]

