    def __init__(self, clock, gateway, token_ttl=3600):
        self._clock = clock
        self._gateway = gateway
        self._ttl = token_ttl
        self._lock = threading.RLock()
        self._users = {}      # username -> (salt, hash)
        self._tokens = {}     # token -> (username, created)
        self._docs = {}       # id -> dict (internal, includes _seq)
        self._doc_counter = itertools.count(1)
        self._cursors = {}    # cursor -> (username, last_seq)
        self._payments = {}   # username -> list of payments
        self._pay_keys = {}   # (username, key) -> {"amount": int, "payment": dict|None}
        self._pay_counter = itertools.count(1)

    # ---- helpers ----
    @staticmethod
    def _hash(password, salt):
        return hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, 1000)

    def _auth(self, token):
        if not isinstance(token, str):
            return None
        entry = self._tokens.get(token)
        if entry is None:
            return None
        user, created = entry
        if self._clock.now() < created + self._ttl:
            return user
        return None

    @staticmethod
    def _public(doc):
        return {k: doc[k] for k in ("id", "owner", "title", "content", "created_at")}

    @staticmethod
    def _valid_doc(title, content):
        if not isinstance(title, str) or not (1 <= len(title) <= 200):
            return False
        if not isinstance(content, str) or len(content) > 100000:
            return False
        return True

    def _user_docs(self, user):
        docs = [d for d in self._docs.values() if d["owner"] == user]
        docs.sort(key=lambda d: d["_seq"])
        return docs

    def _own(self, user, doc_id):
        if not isinstance(doc_id, str):
            return None
        d = self._docs.get(doc_id)
        if d is None or d["owner"] != user:
            return None
        return d

    # ---- auth ----
    def register(self, username, password):
        with self._lock:
            if not isinstance(username, str) or not _USERNAME_RE.fullmatch(username):
                return 400, None
            if not isinstance(password, str) or len(password) < 8:
                return 400, None
            if username in self._users:
                return 409, None
            salt = secrets.token_bytes(16)
            self._users[username] = (salt, self._hash(password, salt))
            return 201, None

    def login(self, username, password):
        with self._lock:
            if not isinstance(username, str) or not isinstance(password, str):
                return 401, None
            rec = self._users.get(username)
            if rec is None:
                return 401, None
            salt, h = rec
            if not hmac.compare_digest(h, self._hash(password, salt)):
                return 401, None
            token = secrets.token_hex(16)
            while token in self._tokens:
                token = secrets.token_hex(16)
            self._tokens[token] = (username, self._clock.now())
            return 200, {"token": token}

